<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientResponseTypesJsonAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientResponseTypesJsonAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientResponseTypesJsonAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getResponseTypesJson returns null on a freshly created holder.
     */
    public function testResponseTypesJsonNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientResponseTypesJsonAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isResponseTypesJsonAssigned());
        $this->assertNull($holder->getResponseTypesJson());
    }
}
class ImplWithTrustedClientResponseTypesJsonAttributeHolderUnitTest
{
    use TrustedClientResponseTypesJsonAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedResponseTypesJsonRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultResponseTypesJson();
    }
}
